"""Benchmark: prompt volume generated by the EvoMe fast + slow paths.

This script measures how many LLM calls and how many prompt *characters* the
EvoMe runtime produces for a fixed list of user turns. It does NOT call any
real LLM API: it drives the runtime with a `RecordingLLM` that wraps the
project's existing `FakeLLM` (from `tests/test_workflow.py`) and records every
`chat` / `stream_chat` / `json_chat` invocation before delegating to the fake.

What it measures
----------------
- Every call the runtime makes through its LLM adapter: the fast-path answer
  plus the slow-path gates / post-turn assessor / context builder / reflection /
  relation judge.
- For each call: the inferred purpose (using the same
  `DeepSeekClient._infer_purpose` markers the production client uses), the
  method name, and the total number of characters across all message contents.

Limitations
-----------
- It counts *prompt characters*, not billed tokens. No tokenizer is applied and
  provider pricing, output tokens, caching and retries are ignored. Use it for
  relative comparison only (e.g. EVOME_SLOW_LOOP_EVERY_N_TURNS=1 vs 2).
- The slow path is driven to completion after each turn via
  `wait_for_background`, which is stricter than production (production does not
  block on the slow job). Call volume per turn is unaffected by this.
- Qdrant retrieval is bypassed because the runtime is backed by an in-memory
  SQLite database (same behavior as the pytest fixtures); Qdrant does not make
  LLM calls, so this does not affect prompt volume.

Safety
------
- Never opens the real `evome.db`: an in-memory SQLite database is used and
  `EVOME_DB_URL` / `EVOME_QDRANT_PATH` are redirected to temporary locations
  before the app modules are imported.
- No existing project file is modified.

Usage
-----
    .venv\\Scripts\\python.exe scripts\\benchmark_token_cost.py [num_turns]

    # compare cadences (set the env var as a process variable so it wins over .env)
    $env:EVOME_SLOW_LOOP_EVERY_N_TURNS=1; .venv\\Scripts\\python.exe scripts\\benchmark_token_cost.py
    $env:EVOME_SLOW_LOOP_EVERY_N_TURNS=2; .venv\\Scripts\\python.exe scripts\\benchmark_token_cost.py
"""

from __future__ import annotations

import os
import shutil
import sys
import tempfile
import threading
from pathlib import Path

# ---------------------------------------------------------------------------
# 1. Redirect persistence to temporary locations BEFORE importing app modules.
#    app.config reads the environment at import time, so this must come first.
# ---------------------------------------------------------------------------
_REPO_ROOT = Path(__file__).resolve().parents[1]
_TMP_DIR = tempfile.mkdtemp(prefix="evome_bench_")
_TMP_QDRANT_DIR = os.path.join(_TMP_DIR, "evome_qdrant")
os.makedirs(_TMP_QDRANT_DIR, exist_ok=True)
_TMP_DB_FILE = os.path.join(_TMP_DIR, "evome_bench.db")

# Force the global engine created by app.database to point away from evome.db.
os.environ["EVOME_DB_URL"] = "sqlite:///" + _TMP_DB_FILE.replace("\\", "/")
os.environ["EVOME_QDRANT_PATH"] = _TMP_QDRANT_DIR
# NOTE: EVOME_SLOW_LOOP_EVERY_N_TURNS is intentionally NOT set here so the
# caller's process environment (which overrides .env) decides the cadence.

if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

from sqlalchemy import create_engine  # noqa: E402
from sqlalchemy.orm import sessionmaker  # noqa: E402
from sqlalchemy.pool import StaticPool  # noqa: E402

from app import config as app_config  # noqa: E402
from app.database import Base  # noqa: E402
import app.models  # noqa: E402,F401  (register ORM tables on Base.metadata)
from app.llm import DeepSeekClient  # noqa: E402
from app.runtime import EvoMeRuntime  # noqa: E402
from tests.test_workflow import FakeLLM  # noqa: E402


# ---------------------------------------------------------------------------
# 2. Fixed prompt list. The SAME list is used for every run so results are
#    comparable across cadence settings.
# ---------------------------------------------------------------------------
PROMPTS = [
    # 1. short greeting (chitchat -> audit only)
    "你好！",
    # 2. definitional question (ordinary Q&A -> audit only)
    "请解释一下 EvoMe 这个项目的设计目标是什么？",
    # 3. debugging task (structural -> evolution lane)
    "我在运行测试时遇到一个报错，请帮我定位并排查这个异常的根本原因。",
    # 4. architecture-design task (structural + complex -> full chain)
    "这是一个复杂任务，请帮我设计 EvoMe 的模块边界、职责划分和数据流。",
    # 5. user-correction message (feedback + personal world -> both lanes)
    "你刚才的回答不对，我正在开发 EvoMe，请按正确的方式重新说明。",
    # 6. planning task (structural -> evolution lane)
    "请帮我规划接下来三个阶段的开发计划，并梳理每个阶段的交付物。",
]


# ---------------------------------------------------------------------------
# 3. Recording LLM: wraps the project FakeLLM and records every call.
# ---------------------------------------------------------------------------
class RecordingLLM(FakeLLM):
    """FakeLLM that records prompt volume for each LLM call.

    Records the method name, inferred purpose (via the production
    `DeepSeekClient._infer_purpose` markers, falling back to the method's own
    default), the total prompt character count, and an 80-char system-prompt
    snippet for debugging. Then delegates to FakeLLM so the pipeline keeps
    working exactly as in the existing tests.
    """

    def __init__(self) -> None:
        self.records: list[dict] = []
        self._lock = threading.Lock()

    # -- helpers ----------------------------------------------------------
    @staticmethod
    def _prompt_chars(messages) -> int:
        total = 0
        for message in messages or []:
            try:
                total += len(str(message.get("content", "")))
            except AttributeError:
                total += len(str(message))
        return total

    @staticmethod
    def _system_snippet(messages) -> str:
        for message in messages or []:
            try:
                if str(message.get("role", "")).lower() == "system":
                    return str(message.get("content", ""))[:80]
            except AttributeError:
                continue
        return ""

    @staticmethod
    def _resolve_purpose(messages, explicit, fallback) -> str:
        if explicit:
            return str(explicit)
        try:
            return DeepSeekClient._infer_purpose(messages, fallback=fallback)
        except Exception:
            return fallback

    def _record(self, messages, method: str, purpose: str) -> None:
        entry = {
            "method": method,
            "purpose": purpose,
            "prompt_chars": self._prompt_chars(messages),
            "system_snippet": self._system_snippet(messages),
        }
        with self._lock:
            self.records.append(entry)

    # -- LLM adapter surface (matches DeepSeekClient) ---------------------
    def chat(self, messages, temperature=0.4, *, purpose=None, max_tokens=None):
        resolved = self._resolve_purpose(messages, purpose, "fast_chat")
        self._record(messages, "chat", resolved)
        return super().chat(messages, temperature)

    def stream_chat(self, messages, temperature=0.4, *, purpose="fast_chat", max_tokens=None):
        resolved = self._resolve_purpose(messages, purpose, "fast_chat")
        self._record(messages, "stream_chat", resolved)
        # Delegate to the base fake (bypassing our recording `chat`) and stream.
        text = super().chat(messages, temperature)
        if text:
            yield text

    def json_chat(self, messages, temperature=0.1, *, purpose=None, max_tokens=None):
        resolved = self._resolve_purpose(messages, purpose, "json_internal")
        self._record(messages, "json_chat", resolved)
        return super().json_chat(messages, temperature)


# ---------------------------------------------------------------------------
# 4. Reporting helpers
# ---------------------------------------------------------------------------
def _print_summary(llm: RecordingLLM, *, skipped: int, turns: int) -> None:
    by_purpose: dict[str, dict[str, int]] = {}
    total_calls = 0
    total_chars = 0

    for entry in llm.records:
        bucket = by_purpose.setdefault(entry["purpose"], {"calls": 0, "chars": 0})
        bucket["calls"] += 1
        bucket["chars"] += entry["prompt_chars"]
        total_calls += 1
        total_chars += entry["prompt_chars"]

    print("BENCH|---- per-purpose prompt volume ----")
    for purpose in sorted(by_purpose):
        stats = by_purpose[purpose]
        print(
            f"BENCH|purpose|{purpose}|calls={stats['calls']}"
            f"|prompt_chars={stats['chars']}"
        )
    print("BENCH|---- totals ----")
    print(f"BENCH|turns|{turns}")
    print(f"BENCH|total_calls|{total_calls}")
    print(f"BENCH|total_prompt_chars|{total_chars}")
    print(f"BENCH|skipped_by_cadence|{skipped}")


# ---------------------------------------------------------------------------
# 5. Main
# ---------------------------------------------------------------------------
def main() -> int:
    num_turns = len(PROMPTS)
    if len(sys.argv) > 1:
        try:
            num_turns = max(1, min(int(sys.argv[1]), len(PROMPTS)))
        except ValueError:
            print(f"BENCH|warning|invalid turn count {sys.argv[1]!r}; using {len(PROMPTS)}")

    prompts = PROMPTS[:num_turns]
    cadence = app_config.EVOME_SLOW_LOOP_EVERY_N_TURNS

    print(f"BENCH|env|EVOME_SLOW_LOOP_EVERY_N_TURNS={cadence}")
    print(f"BENCH|env|EVOME_QDRANT_PATH={os.environ['EVOME_QDRANT_PATH']}")
    print(f"BENCH|env|EVOME_DB_URL={os.environ['EVOME_DB_URL']}")
    print(f"BENCH|python|{sys.executable}")

    # In-memory SQLite (StaticPool) so nothing touches evome.db and the
    # background thread shares the same database, exactly like pytest.
    engine = create_engine(
        "sqlite://",
        connect_args={"check_same_thread": False},
        poolclass=StaticPool,
    )
    Base.metadata.create_all(bind=engine)
    Session = sessionmaker(bind=engine, expire_on_commit=False)

    llm = RecordingLLM()
    db = Session()
    runtime = EvoMeRuntime(db, llm=llm, session_id="benchmark-session")

    skipped = 0
    try:
        for index, prompt in enumerate(prompts, 1):
            result = runtime.stream_run(prompt, on_token=lambda _t: None)
            status = result.get("background_status")
            job_id = result.get("background_job_id")
            if status == "skipped_by_cadence":
                skipped += 1
            if job_id is not None:
                # Block until the slow job's LLM calls are recorded before the
                # next turn, so attribution stays clean.
                runtime.wait_for_background(job_id, timeout=180)
            print(
                f"BENCH|turn|{index}|status={status}"
                f"|response_chars={len(result.get('response', ''))}"
            )
        runtime.shutdown(wait=True)
    finally:
        try:
            runtime.shutdown(wait=True)
        except Exception:
            pass
        db.close()
        engine.dispose()

    _print_summary(llm, skipped=skipped, turns=len(prompts))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    finally:
        shutil.rmtree(_TMP_DIR, ignore_errors=True)
